import{_ as n,l as d,o as a,c as i,v as o,p as l,x as r,d as c,i as s,S as _}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"Ray 2.58 KV-aware 路由","description":"","frontmatter":{"title":"Ray 2.58 KV-aware 路由","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ray-kv-aware-routing.md","filePath":"llm/ray-kv-aware-routing.md","lastUpdated":1789023840000}'),E={name:"llm/ray-kv-aware-routing.md"};function p(R,e,u,A,h,f){const t=d("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="ray-2-58-kv-aware-路由" tabindex="-1">Ray 2.58 KV-aware 路由 <a class="header-anchor" href="#ray-2-58-kv-aware-路由" aria-label="Permalink to &quot;Ray 2.58 KV-aware 路由&quot;">​</a></h1><div class="epigraph"><p>只追 KV 重叠会把所有共享前缀打到同一副本；还要加上这条副本上还剩多少 prefill 与 decode 活。</p><footer>—— Ray 2.58.0 发行说明；Ray Serve LLM *KV-aware routing* 用户指南</footer></div><p>集群路由若只做会话哈希或提示前缀树，看不见引擎里块的创建与驱逐，也不看见这条副本已经在算多少 token。Ray Serve LLM 在 2.57 预览、<strong>2.58.0 收完</strong> KV 与 token 感知路由：<code>KVAwareRouter</code> 根据 vLLM 的 KV 事件估计重叠，再叠上副本的 token load，把请求送到估计负载最低的引擎。概念层见 <a href="/llm/kv-aware-routing">KV 感知路由</a>；本篇钉 2.58 的控制面：决策做在 <code>LLMRouter</code> 入口副本里、事件广播、CPU 卸载也算命中、以及 alpha 限制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>轮询摊请求，对无状态服务正确，对带 KV 的 LLM 会把同一系统提示在 \\(R\\) 个副本上各算一遍。一致性哈希按 <code>x-session-id</code> 粘滞，多轮友好，但长会话会把一张卡打满，其它卡空着。<code>PrefixCacheAffinityRouter</code> 在网关侧用提示文本近似缓存，队列失衡时退回 power-of-two choices，仍然不是引擎块表。真正缺的是：<strong>每张卡现在有哪些 KV 块、每张卡还剩多少 prefill/decode 工作</strong>。</p><p>若把选择做成集群里唯一的 actor，每个请求一次 RPC，入口一多就成热点；actor 挂了，全局负载视图一起没。2.58 把选择挪进已经位于路径上的 ingress 副本，去掉这条同步 RPC。代价是多 ingress 必须同步 KV 事件与负载，视图是最终一致，不是线性一致。</p><h3 id="重叠不是唯一目标" tabindex="-1">重叠不是唯一目标 <a class="header-anchor" href="#重叠不是唯一目标" aria-label="Permalink to &quot;重叠不是唯一目标&quot;">​</a></h3><p>Anyscale 的配套说明把问题说死：只优化 KV 复用，热前缀会吸干单个引擎，TTFT 反而差。正确目标是 <strong>token load</strong>：扣掉 GPU 上已有重叠之后，这条请求还要做多少 prefill，再加上该副本正在进行的 prefill 与 decode。CPU 上的卸载块也算重叠，但信用低于 GPU 块，因为要先搬回 HBM。</p><p><span class="marginnote">文档标明 <code>KVAwareRouter</code> 仍是 alpha。API、环境变量与 Dynamo 选择服务的权重名可能在稳定前改。不要把 2.58 的类路径写进不可改的 Helm 里当永久合同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>安装选择服务：<code>pip install &quot;ai-dynamo&gt;=1.4.0&quot;</code>。启动前三个环境变量必须齐：<code>RAY_SERVE_ENABLE_HA_PROXY=1</code>、<code>RAY_SERVE_LLM_ENABLE_DIRECT_STREAMING=1</code>、<code>RAY_SERVE_INGRESS_REQUEST_ROUTER_FORWARD_BODY=1</code>。路由按 prompt token 打分，所以 HAProxy 要把请求体转到 ingress；体超过缓冲区（默认 256 KiB）会被截断，指标 <code>serve_haproxy_ingress_router_truncations_total</code> 上涨时再加大，内存与 TTFT 会一起涨。</p><p>配置是把 <code>request_router_class=KVAwareRouter</code> 放进 <code>LLMConfig.deployment_config.request_router_config</code>。引擎侧打开 <code>enable_prefix_caching</code>。2.58 的 #65063 让原生 CPU 卸载事件进入同一套索引：<code>OffloadingConnector</code> 发出 <code>medium=&quot;CPU&quot;</code> 的 BlockStored/Removed，选择服务把 HostPinned 层算进重叠。引擎参数形态是 <code>kv_offloading_backend=&quot;native&quot;</code> 加每副本 CPU 缓存 GiB。</p><p>请求路径：客户端 → HAProxy → 某 <code>LLMRouter</code> 入口（本地 tokenize + Dynamo 打分）→ HAProxy 把请求送到选中的 <code>LLMServer</code> → 直接流式回客户端。KV 生命周期事件广播到<strong>所有</strong> ingress；ingress 之间异步同步 token load。Token 经旁路发给引擎，避免引擎再 tokenize；旁路是尽力而为，过期则引擎重做 tokenize。<code>RAY_SERVE_LLM_KV_TOKEN_STAGING_*</code> 控制暂存 TTL、条数与字节。</p>',13)),(a(),l(_,null,{default:r(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLI%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20HAP%5B%22HAProxy%22%5D%0A%20%20HAP%20--%3E%20ING%5B%22LLMRouter%EF%BC%9Atokenize%20%2B%20%E6%89%93%E5%88%86%22%5D%0A%20%20ENG%5B%22vLLM%20KV%20%E4%BA%8B%E4%BB%B6%20ZMQ%22%5D%20--%3E%20ING%0A%20%20ING%20--%3E%20HAP%0A%20%20HAP%20--%3E%20R%5B%22%E9%80%89%E4%B8%AD%E7%9A%84%20LLMServer%22%5D%0A%20%20R%20--%3E%20CLI%0A%20%20R%20--%3E%20LOAD%5B%22%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%EF%BC%9Aprefill%2Fdecode%2F%E7%BB%93%E6%9D%9F%22%5D%0A%20%20LOAD%20--%3E%20ING%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="打分权重" tabindex="-1">打分权重 <a class="header-anchor" href="#打分权重" aria-label="Permalink to &quot;打分权重&quot;">​</a></h3><p><code>runtime_env</code> 里的 <code>DYN_*</code> 传给 ingress 上的选择服务。<code>DYN_ROUTER_PREFILL_LOAD_SCALE</code>（默认 1）拉高则偏 prefill 重的流量；<code>DYN_ROUTER_KV_OVERLAP_SCORE_CREDIT</code> 控制 GPU 重叠能抵多少 prefill，设 0 则只看负载；<code>DYN_ROUTER_KV_OVERLAP_SCORE_CREDIT_DECAY</code> 在副本已经堆积时衰减命中红利，避免亲和把忙卡越打越忙；<code>DYN_ROUTER_DECODE_ACTIVE_REQUEST_WEIGHT</code> 给「正在服务的请求数」加成本。Decode 进度上报默认关（<code>RAY_SERVE_LLM_ENABLE_DECODE_BLOCK_PROGRESS</code>），打开更准，但每个引擎要向每个 ingress 发更新，高并发有网络税。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Token load 用 KV 块当单位。Prefill 项：未命中 token 加上该副本已在飞的 prefill；GPU 块全额抵扣，CPU 块打折。Decode 项：活跃请求的 KV 块，按 <code>max_tokens</code> 估计剩余输出加权。请求去估计总和最低的副本。这把 <a href="/llm/prefix-aware-autoscaling">前缀感知扩缩容</a> 里「利用 vs 探索」收成一个标量，而不是两段启发式。</p><p>入口侧 tokenize 必须与引擎同一 renderer / chat 模板，否则重叠按 token id 计算会系统性算错——差一个 BOS 就整段前缀对不上。这是 ingress CPU 成为瓶颈的原因，也是 <code>RAY_SERVE_INGRESS_ROUTER_REPLICAS_PER_NODE</code> 默认 1、可调到 2 的原因。视图最终一致：刚写入的 KV 块可能尚未出现在另一个 ingress 的树上，短窗口内会次优路由，不应假设全局精确命中。</p><p><span class="marginnote">2.58 还把 tokenization 放在进程内、token 带外传输，使引擎跳过二次分词（#64642、#64920、#65095）。这是延迟路径优化，不是正确性必需：暂存丢失时引擎回退到自己分词，路由决策已经做完，最坏是这次没命中缓存。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>文档限制：只支持直接流式；每个应用一个模型；无 LoRA / multiplex 感知路由；<strong>还不给数据并行 rank 打分</strong>；<strong>还不支持 PD 分离</strong>（均写 planned）。均匀、短提示、无共享前缀的流量，额外开销可能付不出。HAProxy 截断体会让长多模态请求被错误打分。多租户下 KV 事件是缓存元数据，键必须含模型与模板版本，与引擎前缀缓存同一套指纹。</p><h3 id="和文本前缀路由、会话哈希怎么选" tabindex="-1">和文本前缀路由、会话哈希怎么选 <a class="header-anchor" href="#和文本前缀路由、会话哈希怎么选" aria-label="Permalink to &quot;和文本前缀路由、会话哈希怎么选&quot;">​</a></h3><p><code>PrefixCacheAffinityRouter</code> 不依赖 Dynamo、不要求 KV 事件套接字，用提示文本在网关侧建树，适合「还没有 vLLM 事件、但共享长前缀」的过渡。它近似引擎状态，队列一歪就退回 power of two，热前缀仍可能打偏。<code>ConsistentHashRouter</code> 要客户端带 <code>x-session-id</code>，多轮对话稳，但长短会话不均时会把单卡打满。<code>KVAwareRouter</code> 吃的是异构长度、GPU 已近满、以及前缀共享超出系统提示的流量；代价是直接流式约束、每应用单模型、以及选择服务的运维面。同一 <code>request_router_config</code> 可以换类，先用哈希把会话稳住，再在观测到假命中或热卡之后切 KV-aware，而不是第一天就上 alpha。</p><p>扩容时新副本的 KV 树是空的，选择服务会暂时把它看成「无重叠、负载低」而灌冷 prefill，直到事件追上。这与 <a href="/llm/prefix-aware-autoscaling">前缀感知扩缩容</a> 的「先复制热前缀再接流量」要配合：只加空副本、立刻让 KV-aware 看见，等于用路由把缓存打散。缩容相反，先从选择集摘掉、等块引用归零，再下实例。</p><p><span class="marginnote">出处：<a href="https://github.com/ray-project/ray/releases/tag/ray-2.58.0%EF%BC%88KV" target="_blank" rel="noreferrer">https://github.com/ray-project/ray/releases/tag/ray-2.58.0（KV</a> cache and token aware request routing、CPU KV 感知 #65063）；<a href="https://docs.ray.io/en/master/serve/llm/user-guides/kv-aware-routing.html%E3%80%82%E9%80%89%E6%8B%A9%E6%9C%8D%E5%8A%A1%E7%BB%86%E8%8A%82%E8%A7%81" target="_blank" rel="noreferrer">https://docs.ray.io/en/master/serve/llm/user-guides/kv-aware-routing.html。选择服务细节见</a> NVIDIA Dynamo standalone selection service 文档。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Ray 2.58 的 <code>KVAwareRouter</code> 用引擎 KV 事件加 token load 选副本，而不是只做前缀哈希。</li><li>决策在 <code>LLMRouter</code> ingress 内完成；KV 事件广播，负载最终一致。</li><li>CPU 卸载块计入命中但信用更低；token 在入口分词并带外传递。</li><li>需要 HAProxy、直接流式、转发请求体；alpha，且暂不支持 DP 与 PD 分离。</li><li>权重用 <code>DYN_ROUTER_*</code> 按 prefill/decode 形态调。</li><li>出处：Ray 2.58 发行说明与 Serve LLM 用户指南。</li></ul>',14))])}const P=n(E,[["render",p]]);export{g as __pageData,P as default};
